-- pruefung_startdatum — 2-year duration and the 6/12/18/24-month schedule are printed
update public.fields set verification_status='verified_against_standard', verification_quote='Die 2-jährige Prüfung wird in einem klimagesteuerten Gewächshaus unter Verwendung von Phragmites australis (Schilf) durchgeführt. Die zu untersuchenden Produkte, die mehrere Nahtstellen bzw. eine Arbeitsunterbrechungsfuge aufweisen müssen, werden in 8 Prüfgefäße eingebaut. Weitere 3 Gefäße gehen ohne Abdichtung in die Prüfung. Sie dienen als Kontrolle für das Pflanzenwachstum. — printed p.12 | Die Ausbreitung der Testpflanzen wird im Abstand von 6 Monaten erfasst. Eine ausreichende Wuchsleistung ist gegeben, wenn die Pflanzen in den Prüfgefäßen im Durchschnitt folgende Bestandsdichte aufweisen: 1. Zwischenauswertung (nach 6 Monaten) ≥ 80 Halme/Gefäße — printed p.10', verification_note='md-verified 2026-09-05 (§4 p.12, §3.7 p.10) [VC]; 2-year duration and the 6/12/18/24-month schedule are printed; the Musterbericht prints the period as "Die Prüfung wurde von >> Monat Jahr << bis >> Monat Jahr << durchgeführt" (p.27); the start day is a record date', verified_at=now() where id='e9bbded7-39a8-494d-a042-62f70648bd32' and verification_status not in ('verified_against_standard','corrected');

