update public.fields set verification_status='verified_against_standard', verification_quote='Das Ergebnis der geprüften Werkstoffe ist nicht übertragbar auf den Ein- und Durchdringungswiderstand gegen Pflanzen mit sehr starkem Rhizomwachstum, z. B. Bambus-Arten. Bei Verwendung derartiger Pflanzenarten sind über den befundenen Ein- und Durchdringungschutz hinausgehende bauliche Vorkehrungen zu treffen und besondere Pflegemaßnahmen vorzusehen. — printed p.8', verification_note='md-verified 2026-09-05 (§2 p.8) [VC]; attestation field for REQ-02 (§2 non-transferability to Bambus-Arten)', verified_at=now() where id='9ab06637-2fb5-4927-a64e-3eae65b03f88' and verification_status not in ('verified_against_standard','corrected');

