-- abdichtungsart — enum splits the printed "Kunststoff- und Elastomerbahnen" into two tokens (EKOWAI granularity)
update public.fields set verification_status='verified_against_standard', verification_quote='Dazu gehören z. B. folgende Abdichtungen: Bitumenbahnen; Kunststoff- und Elastomerbahnen; Flüssigabdichtungen; Gussasphalt; GUP-Beschichtungen für alle Ausbildungsformen von Gewässern im Garten-, Landschafts- und Sportplatzbau. Das Verfahren beinhaltet die Prüfung einzelner Produkte für die Herstellung von Abdichtungsschichten von Gewässern inklusive der zugehörigen Fügetechnik. Die Prüfung eines Abdichtungssystems, d. h. eines aus mehreren Funktionsschichten bestehenden Aufbaus oder einer zusätzlichen Kaschierung der Gewässerabdichtung ist nicht zulässig. — printed p.8', verification_note='md-verified 2026-09-05 (§2 p.8) [VC]; enum splits the printed "Kunststoff- und Elastomerbahnen" into two tokens (EKOWAI granularity); the §2 list is "z. B." (open)', verified_at=now() where id='82a1f192-f146-4d5c-a23a-2ea2a332e812' and verification_status not in ('verified_against_standard','corrected');

