-- wachstumshemmende_wirkstoffe
update public.fields set verification_status='verified_against_standard', verification_quote='In die Fläche oder Naht bzw. Arbeitsunterbrechungsfuge ≤ 5 mm eingewachsene Rhizome bei Produkten, die wachstumshemmende Wirkstoffe enthalten, da hierbei die hemmende Wirkung erst nach dem Eindringen der Rhizome entfaltet werden kann. Um eine derartige Bewertung zu ermöglichen, sind solche Produkte vom Hersteller zu Prüfungsbeginn eindeutig als "mit wachstumshemmenden Wirkstoffen versehen" zu definieren. — printed p.10', verification_note='md-verified 2026-09-05 (§3.9 p.10) [VC]', verified_at=now() where id='cfd95ef9-a6b0-4e9c-a88c-428cae3984ca' and verification_status not in ('verified_against_standard','corrected');

