-- fuegetechniken_angewandt — §6 p.16 lists "angewandte Fügetechniken" among the Angaben des Herstellers
update public.fields set verification_status='verified_against_standard', verification_quote='Es ist zulässig, in der Prüfung unterschiedliche Fügetechniken zu kombinieren, sofern diese ausnahmslos stoffhomogene Nahtverbindungen zum Ziel haben (z. B. Quellschweißung – mit einem Lösungsmittel, das sich verflüchtigt – und Warmgasschweißung). Derartige Nahtverbindungen werden als gleichwertig angesehen. Im Gegensatz dazu gelten Kombinationen von klebefreien Verbindungen und Verbindungen mit Klebemasse oder von Verbindungen mit 2 unterschiedlichen Klebemassen als nicht gleichwertig. — printed p.10', verification_note='md-verified 2026-09-05 (§3.8 p.10) [VC]; §6 p.16 lists "angewandte Fügetechniken" among the Angaben des Herstellers', verified_at=now() where id='ff548b1b-860c-4eea-8999-871139ba0af8' and verification_status not in ('verified_against_standard','corrected');

