update public.fields set verification_status='verified_against_standard', verification_quote='Aus versuchstechnischen Gründen kann es bei Beschichtungen (z. B. Flüssigabdichtungen, Gussasphalt oder GUP-Beschichtungen) erforderlich sein, unter der Beschichtung eine gesonderte Lage einzubauen. Dies ist gestattet, sofern der Hersteller eindeutig erklärt, dass die Rhizomfestigkeit einzig durch die zuoberst aufgetragene Beschichtung bewirkt wird. — printed p.8', verification_note='md-verified 2026-09-05 (§2 p.8) [VC]', verified_at=now() where id='0d1581a3-15e0-4b73-a070-2edb9e9c3397' and verification_status not in ('verified_against_standard','corrected');

