update public.fields set verification_status='verified_against_standard', verification_quote='Es ist ein Gewächshaus vorzusehen, das mit einer regelbaren Heizung und Lüftung ausgestattet ist. Die Heizung ist so einzustellen, dass die Innentemperatur tagsüber bei (18 ±3) °C und während der Nacht bei (16 ±3) °C liegt. Ab einer Innentemperatur von (22 ±3) °C ist das Gewächshaus zu lüften. Eine anhaltende Innentemperatur > 35 °C ist zu vermeiden. — printed p.13', verification_note='md-verified 2026-09-05 (§5.1 p.13) [VC]; (18 ±3) °C → REQ-05 15–21', verified_at=now() where id='94fc04a8-5682-45fa-a024-3ab3bb999d68' and verification_status not in ('verified_against_standard','corrected');

