-- gefaess_innenmass_l_mm
update public.fields set verification_status='verified_against_standard', verification_quote='Die Gefäße müssen ein Innenmaß von mindestens 800 x 800 x 250 mm aufweisen (s. Abb. 1). Unter Berücksichtigung einbautechnischer Erfordernisse (z. B. bei Abdichtungen mit einer Dicke über rund 50 mm) kann es notwendig sein, größere Gefäße einzusetzen. Alle nachfolgenden Angaben (z. B. Düngung, Pflanzdichte), die sich auf dieses Mindestmaß beziehen, sind an die ggf. größer dimensionierten Gefäße anzupassen. — printed p.13', verification_note='md-verified 2026-09-05 (§5.2 p.13, Abb.1 p.13) [VC]', verified_at=now() where id='c403d206-8423-45e2-9de8-9d3934395984' and verification_status not in ('verified_against_standard','corrected');

