-- wasserablauf_durchmesser_mm
update public.fields set verification_status='verified_against_standard', verification_quote='Die Gefäße sind aus korrosionsfesten Materialien mit stabiler Wandung herzustellen. Das Material muss pflanzenverträglich sein. Die Kontrollgefäße sind wasserdicht auszuführen. Der Boden der Prüfgefäße muss über einen Wasserablauf verfügen, um Undichtigkeiten (und somit Beschädigungen der zu prüfenden Abdichtung) während der Prüfung feststellen zu können. — printed p.13 | Abb. 1: Aufbau der Gefäße mit Mindestangaben für die Innenmaße. Der Wasserablauf (Ø 40 mm) ist nur bei den Prüfgefäßen vorzusehen. Die Kontrollgefäße sind wasserdicht abzubilden. — printed p.13', verification_note='md-verified 2026-09-05 (§5.2 p.13, Abb.1 p.13) [VC]', verified_at=now() where id='07eb0caa-461b-49f5-b0d8-801378953ec1' and verification_status not in ('verified_against_standard','corrected');

-- anzahl_pruefgefaesse
update public.fields set verification_status='verified_against_standard', verification_quote='Für jede zu untersuchende Abdichtung sind 8 Prüfgefäße mit Wasserablauf erforderlich. Zusätzlich sind pro Prüfung – unabhängig von der Anzahl der zu prüfenden Abdichtungen – 3 Kontrollgefäße (ohne Wasserablauf) vorzusehen. — printed p.14 | Die 2-jährige Prüfung wird in einem klimagesteuerten Gewächshaus unter Verwendung von Phragmites australis (Schilf) durchgeführt. Die zu untersuchenden Produkte, die mehrere Nahtstellen bzw. eine Arbeitsunterbrechungsfuge aufweisen müssen, werden in 8 Prüfgefäße eingebaut. Weitere 3 Gefäße gehen ohne Abdichtung in die Prüfung. Sie dienen als Kontrolle für das Pflanzenwachstum. — printed p.12', verification_note='md-verified 2026-09-05 (§5.2 p.14, §4 p.12) [VC]', verified_at=now() where id='6940d690-81fd-4937-a03d-7c5fcc9de29f' and verification_status not in ('verified_against_standard','corrected');

