-- ---------- FLLTP-RHZ-08 Testpflanzen-Qualität ----------

-- testpflanze_art — §1 p.7: "Die Prüfung der Rhizomfestigkeit von Gewässerabdichtungen erfolgt deshalb ausschließlich mit Phragmites australis."
update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Prüfung ist folgende Pflanzenart in der angegebenen Qualität einzusetzen: Phragmites australis (Schilf) im 9 x 9 Container. Je Gefäß von 800 x 800 mm sind 8 Pflanzen vorzusehen. Es ist auf eine gleichmäßige Pflanzenqualität zu achten. — printed p.15 | Die 2-jährige Prüfung wird in einem klimagesteuerten Gewächshaus unter Verwendung von Phragmites australis (Schilf) durchgeführt. Die zu untersuchenden Produkte, die mehrere Nahtstellen bzw. eine Arbeitsunterbrechungsfuge aufweisen müssen, werden in 8 Prüfgefäße eingebaut. Weitere 3 Gefäße gehen ohne Abdichtung in die Prüfung. Sie dienen als Kontrolle für das Pflanzenwachstum. — printed p.12', verification_note='md-verified 2026-09-05 (§5.8 p.15, §4 p.12) [VC]; §1 p.7: "Die Prüfung der Rhizomfestigkeit von Gewässerabdichtungen erfolgt deshalb ausschließlich mit Phragmites australis."', verified_at=now() where id='2e0dfb91-d033-4b73-8a0d-638fd0a43737' and verification_status not in ('verified_against_standard','corrected');

-- testpflanze_container_format — "9 x 9 Container" — text field, no gate
update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Prüfung ist folgende Pflanzenart in der angegebenen Qualität einzusetzen: Phragmites australis (Schilf) im 9 x 9 Container. Je Gefäß von 800 x 800 mm sind 8 Pflanzen vorzusehen. Es ist auf eine gleichmäßige Pflanzenqualität zu achten. — printed p.15', verification_note='md-verified 2026-09-05 (§5.8 p.15) [VC]; "9 x 9 Container" — text field, no gate', verified_at=now() where id='cbf913d9-2517-49f5-8c91-1e86850d5ba1' and verification_status not in ('verified_against_standard','corrected');

-- ---------- FLLTP-RHZ-09 Einbau der Abdichtung in Prüfgefäße ----------

-- vts_untere_schicht_dicke_mm — (20 ±5) mm → REQ-13 15–25
update public.fields set verification_status='verified_against_standard', verification_quote='Nach dem Einbau des ersten Prüfmusters wird die untere Vegetationstragschicht in einer Schichtdicke von (20 ±5) mm eingebaut. Der Bedarf an Substrat liegt bei Gefäßen von 800 x 800 mm bei ca. 12 l. Auf der unteren Vegetationstragschicht wird ein Standrohr in Nähe der Gefäßwand angebracht. — printed p.17', verification_note='md-verified 2026-09-05 (§7.1 p.17) [VC]; (20 ±5) mm → REQ-13 15–25', verified_at=now() where id='da398439-ef3b-45cd-a6a4-701d5b3f4f79' and verification_status not in ('verified_against_standard','corrected');

-- vts_obere_schicht_dicke_mm — (150 ±5) mm → REQ-13 145–155
update public.fields set verification_status='verified_against_standard', verification_quote='Nach dem Einbau des zweiten Prüfmusters wird das zweite Standrohr innerhalb des zweiten Prüfmusters und anschließend die obere Vegetationstragschicht in einer Schichtdicke von (150 ±5) mm eingebaut. Dies entspricht bei Gefäßen von 800 x 800 mm einem Substratvolumen von ca. 100 l. Pro Prüfgefäß von 800 x 800 mm sind acht Pflanzen von Phragmites australis (Schilf) einzusetzen (s. Abb. 4). — printed p.17', verification_note='md-verified 2026-09-05 (§7.1 p.17) [VC]; (150 ±5) mm → REQ-13 145–155', verified_at=now() where id='c727402e-f6a7-4757-9752-1944cf669943' and verification_status not in ('verified_against_standard','corrected');

-- naht_anzahl_wand_eck — sheet products only (REQ-11 conditional on ist_bahnenartig)
update public.fields set verification_status='verified_against_standard', verification_quote='Bei bahnenartigen Abdichtungen werden Teile der Bahn zugeschnitten, am Untersuchungsort in der Verantwortung des Auftraggebers fachtechnisch verbunden und in die Gefäße eingebaut (s. Abb. 2, 4 und 5). Hierbei sind vier Wand-Eck-Nähte, zwei Boden-Eck-Nähte und ein mittig verlaufende T-Naht auszuführen. Es ist zulässig unterschiedliche Fügetechniken anzuwenden, sofern diese gleichwertig sind (s. Abschnitt 2.8). — printed p.17', verification_note='md-verified 2026-09-05 (§7.1 p.17) [VC]; sheet products only (REQ-11 conditional on ist_bahnenartig)', verified_at=now() where id='be653965-c840-4914-900f-f15f88273038' and verification_status not in ('verified_against_standard','corrected');

