update public.fields set verification_status='verified_against_standard', verification_quote='Bei bahnenartigen Abdichtungen werden Teile der Bahn zugeschnitten, am Untersuchungsort in der Verantwortung des Auftraggebers fachtechnisch verbunden und in die Gefäße eingebaut (s. Abb. 2, 4 und 5). Hierbei sind vier Wand-Eck-Nähte, zwei Boden-Eck-Nähte und ein mittig verlaufende T-Naht auszuführen. Es ist zulässig unterschiedliche Fügetechniken anzuwenden, sofern diese gleichwertig sind (s. Abschnitt 2.8). — printed p.17', verification_note='md-verified 2026-09-05 (§7.1 p.17) [VC]; sheet products only (REQ-11 conditional on ist_bahnenartig)', verified_at=now() where id='685bf705-c790-408e-9c9b-68f347e6f5a7' and verification_status not in ('verified_against_standard','corrected');

