-- naht_anzahl_laengs_2_pruefmuster — sheet products only (REQ-11 conditional on ist_bahnenartig)
update public.fields set verification_status='verified_against_standard', verification_quote='Auf die untere Vegetationstragschicht wird das zweite Prüfmuster der Abdichtung um 45° versetzt zum ersten Prüfmuster eingebaut. Bei bahnenartigen Abdichtungen sind zwei Längsnähte erforderlich. Die Ecken dieses Prüfmusters werden gefaltet (s. Abb. 3 bis 5). — printed p.17', verification_note='md-verified 2026-09-05 (§7.1 p.17) [VC]; sheet products only (REQ-11 conditional on ist_bahnenartig)', verified_at=now() where id='34b1dc95-95be-4a0f-8de7-ef21c08c8a5a' and verification_status not in ('verified_against_standard','corrected');

-- arbeitsfuge_zeitabstand_h — non-sheet products only (REQ-12 conditional)
update public.fields set verification_status='verified_against_standard', verification_quote='Nicht bahnenförmige Abdichtungen, wie z. B. Flüssigabdichtungen, Gussasphalt oder GUP-Beschichtungen werden ebenfalls am Untersuchungsort in der Verantwortung des Auftraggebers fachtechnisch in die Gefäße eingebaut. Der Einbau muss in zwei Arbeitsschritten erfolgen, wobei in der Mitte des Gefäßes eine durchgehende Arbeitsunterbrechungsfuge anzuordnen ist. Der Zeitabstand zwischen den beiden Arbeitsschritten muss mindestens 12 Stunden betragen. — printed p.17', verification_note='md-verified 2026-09-05 (§7.1 p.17) [VC]; non-sheet products only (REQ-12 conditional); is_required review STAGED', verified_at=now() where id='45487093-00ea-4206-b0cf-f52706418cdc' and verification_status not in ('verified_against_standard','corrected');

