update public.fields set verification_status='verified_against_standard', verification_quote='Durch zwei eingelassene Rohre (∅ 50 mm, Länge 200 mm) aus pflanzenverträglichen Werkstoffen (z. B. PE) wird in der Vegetationstragschicht die Kontrolle des Wasserstandes und der Wasserqualität sichergestellt. — printed p.9 | Nach dem Einbau des ersten Prüfmusters wird die untere Vegetationstragschicht in einer Schichtdicke von (20 ±5) mm eingebaut. Der Bedarf an Substrat liegt bei Gefäßen von 800 x 800 mm bei ca. 12 l. Auf der unteren Vegetationstragschicht wird ein Standrohr in Nähe der Gefäßwand angebracht. — printed p.17', verification_note='md-verified 2026-09-05 (§3.5 p.9, §7.1 p.17) [VC]; Ø 50 mm / Länge 200 mm printed; no gate', verified_at=now() where id='218b8e1f-6014-409f-9172-f2f627b57dba' and verification_status not in ('verified_against_standard','corrected');

