-- ---------- FLLTP-RHZ-11 Bepflanzung ----------

-- pflanzdichte_pro_gefaess
update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Prüfung ist folgende Pflanzenart in der angegebenen Qualität einzusetzen: Phragmites australis (Schilf) im 9 x 9 Container. Je Gefäß von 800 x 800 mm sind 8 Pflanzen vorzusehen. Es ist auf eine gleichmäßige Pflanzenqualität zu achten. — printed p.15 | Nach dem Einbau des zweiten Prüfmusters wird das zweite Standrohr innerhalb des zweiten Prüfmusters und anschließend die obere Vegetationstragschicht in einer Schichtdicke von (150 ±5) mm eingebaut. Dies entspricht bei Gefäßen von 800 x 800 mm einem Substratvolumen von ca. 100 l. Pro Prüfgefäß von 800 x 800 mm sind acht Pflanzen von Phragmites australis (Schilf) einzusetzen (s. Abb. 4). — printed p.17', verification_note='md-verified 2026-09-05 (§5.8 p.15, §7.1 p.17) [VC]', verified_at=now() where id='71952c30-5997-4086-8dc6-fae20f1bd8b2' and verification_status not in ('verified_against_standard','corrected');

