update public.fields set verification_status='verified_against_standard', verification_quote='Die Düngung erfolgt in monatlichem Abstand. Pro Gabe und Gefäß (800 x 800 mm) werden 5 g Düngemittel (s. Abschnitt 4.7) gelöst in 20 l Wasser appliziert. Die Düngerlösung wird gleichmäßig über die Vegetationstragschicht verteilt. Die erste Gabe wird unmittelbar nach der Bepflanzung verabreicht. — printed p.20 | Abgestorbene Pflanzen sind zu ersetzen. Um die sich entwickelnden Wurzeln und Rhizome der verbleibenden Pflanzen nicht zu stören, ist dies jedoch nur während der ersten drei Monate gestattet. Wird im Prüfungsverlauf keine ausreichende Wuchsleistung erreicht (s. Abschnitt 2.7), ist die Prüfung abzubrechen. — printed p.20', verification_note='md-verified 2026-09-05 (§7.3 p.20) [VC]; anchor date for the first fertiliser dose and the 3-month replacement window; the day itself is a record date; clause_reference "§Bepflanzung" → §7.3 STAGED', verified_at=now() where id='eca1fe70-a6af-4593-9870-1a7f92279f02' and verification_status not in ('verified_against_standard','corrected');

