-- ---------- FLLTP-RHZ-13 Wuchsleistung Zwischenauswertung 6 Monate ----------

-- bestandsdichte_p_avg_6mon — ≥ 80 Halme/Gefäß at 6 months
update public.fields set verification_status='verified_against_standard', verification_quote='Die Ausbreitung der Testpflanzen wird im Abstand von 6 Monaten erfasst. Eine ausreichende Wuchsleistung ist gegeben, wenn die Pflanzen in den Prüfgefäßen im Durchschnitt folgende Bestandsdichte aufweisen: 1. Zwischenauswertung (nach 6 Monaten) ≥ 80 Halme/Gefäße 2. Zwischenauswertung (nach 12 Monaten) ≥ 120 Halme/Gefäße 3. Zwischenauswertung (nach 18 Monaten) ≥ 160 Halme/Gefäße 4. Endauswertung (nach 24 Monaten) ≥ 160 Halme/Gefäße — printed p.10', verification_note='md-verified 2026-09-05 (§3.7 p.10; count rule §8.1 p.21) [VC]; ≥ 80 Halme/Gefäß at 6 months; hand-entered twin of the EQ-1 output bestandsdichte_p_avg (REQ-15 reads this one)', verified_at=now() where id='dd77b49a-9d70-45cd-b9fc-9096bcf00af5' and verification_status not in ('verified_against_standard','corrected');

-- bestandsdichte_k_avg — EQ-2 output, hand-enterable
update public.fields set verification_status='verified_against_standard', verification_quote='Die durchschnittliche Bestandsdichte der Testpflanzen in den Prüf- und Kontrollgefäßen muss während der gesamten Prüfdauer ähnlich hoch sein. Die Bestandsdichte der Testpflanzen in den Prüfgefäßen muss mindestens 80 % der Bestandsdichte der Pflanzen in den Kontrollgefäßen betragen. Hierdurch kann ggf. auf eine Beeinträchtigung der Testpflanzen durch pflanzenschädigende Stoffe der Abdichtung geschlossen werden. — printed p.10 | Anzahl Halme / Gefäß Anzahl Halme / Gefäß Anzahl Halme / Gefäß Anzahl Halme / Gefäß K 1 K 2 K 3 Ø K 1 – K 3 Tab. 1: Bestandsdichte der Testpflanzen in den 8 Prüfgefäßen Tab. 2: Bestandsdichte der Testpflanzen in den 3 Kontrollgefäßen — printed p.30', verification_note='md-verified 2026-09-05 (§3.7 p.10, Anhang 2 Tab.2 p.30) [VC]; EQ-2 output, hand-enterable', verified_at=now() where id='04f872fb-95c9-47f0-a58d-6a70d618ea28' and verification_status not in ('verified_against_standard','corrected');

-- dichte_relativ_prozent — EQ-3 output, hand-enterable
update public.fields set verification_status='verified_against_standard', verification_quote='Die durchschnittliche Bestandsdichte der Testpflanzen in den Prüf- und Kontrollgefäßen muss während der gesamten Prüfdauer ähnlich hoch sein. Die Bestandsdichte der Testpflanzen in den Prüfgefäßen muss mindestens 80 % der Bestandsdichte der Pflanzen in den Kontrollgefäßen betragen. Hierdurch kann ggf. auf eine Beeinträchtigung der Testpflanzen durch pflanzenschädigende Stoffe der Abdichtung geschlossen werden. — printed p.10 | Ø P 1 – P 8 Ø K 1 – K 3 x 100 [...] % % % % Tab. 3: Durchschnittliche Bestandsdichte der Testpflanzen in den 8 Prüfgefäßen bezogen auf die Durchschnittswerte der Testpflanzen in den drei Kontrollgefäßen (Sollwert: ≥ 80 %) — printed p.31', verification_note='md-verified 2026-09-05 (§3.7 p.10, Anhang 2 Tab.3 p.31) [VC]; EQ-3 output, hand-enterable; REQ-16/17/18 read this 6-month value for the 12/18/24-month verdicts (STAGED)', verified_at=now() where id='2214502d-5a2d-44a0-9c57-a8246feb6e71' and verification_status not in ('verified_against_standard','corrected');

-- wuchsleistung_ausreichend — verdict enum values pass/fail are EKOWAI’s
