-- ---------- FLLTP-RHZ-17 Rhizomeindringung & -durchdringung Erfassung ----------

-- rhizomeindringung_flaeche_count
update public.fields set verification_status='verified_against_standard', verification_quote='Rhizomeindringungen liegen vor, wenn in die Fläche oder in die Nähte eines geprüften Produktes Rhizome eingewachsen sind, wobei die unterirdischen Pflanzenteile sich aktiv Hohlräume geschaffen und die Abdichtungsschicht beschädigt haben. Nicht als Rhizomeindringung zu werten, aber im Prüfbericht aufzuführen sind: — printed p.10 | Gemäß der Abschnitte 2.9, 2.10 und 2.12 werden ein- und durchgedrungene Rhizome bei der geprüften Abdichtung in absoluten Zahlen erfasst. Dies erfolgt getrennt für folgende Bereiche bei bahnenartigen Abdichtung: o die Fläche und o die Nähte; bei nicht bahnenförmigen Abdichtungen: o die Fläche und o die Arbeitsunterbrechungsfuge, falls diese erkennbar ist. — printed p.21', verification_note='md-verified 2026-09-05 (§3.9 p.10, §8.2 p.21) [VC]', verified_at=now() where id='b2b7ee9f-c130-4f52-8d39-9d38b48c0b02' and verification_status not in ('verified_against_standard','corrected');

