-- max_eindringtiefe_ueberlappung_mm
update public.fields set verification_status='verified_against_standard', verification_quote='Bei Eindringungen von Rhizomen in den Überlappungsbereich von Nähten ist die maximale Eindringtiefe festzuhalten. Ein- und durchgedrungene Rhizome sind beispielhaft fotografisch zu belegen. Von der untersuchten Abdichtung sind zum Ende der Prüfung Rückstellproben zu entnehmen, die das Ergebnis der Untersuchung dokumentieren. Die Proben sind gemäß Abschnitt 5 zu lagern. — printed p.21', verification_note='md-verified 2026-09-05 (§8.2 p.21) [VC]', verified_at=now() where id='c255ce3e-fdd9-49f6-880d-eba500b1fd33' and verification_status not in ('verified_against_standard','corrected');

-- rhizome_unter_5mm_bei_hemmstoff_count
update public.fields set verification_status='verified_against_standard', verification_quote='In die Fläche oder Naht bzw. Arbeitsunterbrechungsfuge ≤ 5 mm eingewachsene Rhizome bei Produkten, die wachstumshemmende Wirkstoffe enthalten, da hierbei die hemmende Wirkung erst nach dem Eindringen der Rhizome entfaltet werden kann. Um eine derartige Bewertung zu ermöglichen, sind solche Produkte vom Hersteller zu Prüfungsbeginn eindeutig als "mit wachstumshemmenden Wirkstoffen versehen" zu definieren. — printed p.10', verification_note='md-verified 2026-09-05 (§3.9 p.10) [VC]', verified_at=now() where id='2a731a8a-619f-4c1c-917d-6d08f92cfabb' and verification_status not in ('verified_against_standard','corrected');

-- rhizome_in_poren_count
update public.fields set verification_status='verified_against_standard', verification_quote='Nicht als Rhizomeindringung zu werten, aber im Prüfbericht aufzuführen sind: In bereits vorhandene Poren einer Abdichtung (Fläche oder Naht bzw. Arbeitsunterbrechungsfuge) eingewachsene Rhizome (d. h. keine Beschädigung). Um hierbei eine eindeutige Bewertung zu gewährleisten, ist eine Betrachtung der entsprechenden Bereiche der Abdichtung unter dem Mikroskop erforderlich. — printed p.10', verification_note='md-verified 2026-09-05 (§3.9 p.10) [VC]', verified_at=now() where id='81833541-0b00-47df-8912-ca97ea2c5b39' and verification_status not in ('verified_against_standard','corrected');

-- fotos_dokumentiert
update public.fields set verification_status='verified_against_standard', verification_quote='Bei Eindringungen von Rhizomen in den Überlappungsbereich von Nähten ist die maximale Eindringtiefe festzuhalten. Ein- und durchgedrungene Rhizome sind beispielhaft fotografisch zu belegen. Von der untersuchten Abdichtung sind zum Ende der Prüfung Rückstellproben zu entnehmen, die das Ergebnis der Untersuchung dokumentieren. Die Proben sind gemäß Abschnitt 5 zu lagern. — printed p.21', verification_note='md-verified 2026-09-05 (§8.2 p.21) [VC]', verified_at=now() where id='14981283-6827-43e1-98bb-2b3a6f737ccc' and verification_status not in ('verified_against_standard','corrected');

-- rueckstellproben_entnommen — clause_reference "§5" → §6 (2023 numbering) STAGED
update public.fields set verification_status='verified_against_standard', verification_quote='Von der Abdichtung ist vom Prüfinstitut vor und nach der Untersuchung eine Rückstellprobe zu nehmen. Das entnommene Teilstück muss zumindest eine Nahtstelle pro Fügetechnik bzw. eine Arbeitsunterbrechungsfuge enthalten und eine Fläche von mindestens 0,5 m2 aufweisen. Die Rückstellprobe ist bei Temperaturen über 5 °C und unter 25 °C trocken und dunkel beim Prüfinstitut zu lagern. — printed p.16 | Von der untersuchten Abdichtung sind zum Ende der Prüfung Rückstellproben zu entnehmen, die das Ergebnis der Untersuchung dokumentieren. Die Proben sind gemäß Abschnitt 5 zu lagern. — printed p.21', verification_note='md-verified 2026-09-05 (§6 p.16, §8.2 p.21) [VC]; clause_reference "§5" → §6 (2023 numbering) STAGED', verified_at=now() where id='b1ecbd75-9459-4e93-bf02-a5157d927a47' and verification_status not in ('verified_against_standard','corrected');

-- ---------- FLLTP-RHZ-18 Bewertung Rhizomfestigkeit (Gate) ----------

-- abbruchsgrund
update public.fields set verification_status='verified_against_standard', verification_quote='Bei erkennbaren Durchdringungen von Rhizomen am zu prüfenden Produkt ist der Auftraggeber der Untersuchung zu unterrichten. Die Prüfung kann abgebrochen werden. Wird im Prüfungsverlauf keine ausreichende Wuchsleistung der Testpflanzen erzielt (s. 2.7), ist die Prüfung abzubrechen. — printed p.11 | Bei erkennbarer Beschädigung der eingebauten Abdichtung durch Rhizome ist der Auftraggeber zu unterrichten. Die Prüfung kann abgebrochen werden (s. Abschnitt 2.12). — printed p.21', verification_note='md-verified 2026-09-05 (§3.12 p.11, §8.1 p.21) [VC]', verified_at=now() where id='9cabdf11-9832-444c-a6c2-3b8d1c7d2770' and verification_status not in ('verified_against_standard','corrected');

-- pruefergebnis_rhizomfest — enum regulation_reference "§8" for nicht_rhizomfest → §9 (STAGED note)
update public.fields set verification_status='verified_against_standard', verification_quote='Ein Produkt gilt als rhizomfest, wenn in allen Prüfgefäßen nach Ablauf der Prüfdauer keine Rhizomeindringungen gemäß Abschnitt 2.9 sowie keine Rhizomdurchdringungen gemäß Abschnitt 2.10 festzustellen sind. Voraussetzung ist zudem, dass die in der Prüfung verwendeten Pflanzen in den Prüfgefäßen im gesamten Prüfungsverlauf eine ausreichende Wuchsleistung gemäß Abschnitt 2.7 erbracht haben. — printed p.11 | Firmen und Produkte, die ohne Erfolg an der Untersuchung teilgenommen haben, erhalten keinen Prüfbericht, sondern lediglich eine schriftliche Mitteilung mit der begründeten Feststellung, dass sich das Produkt als nicht rhizomfest nach FLL erwiesen hat. — printed p.22', verification_note='md-verified 2026-09-05 (§3.11 p.11, §9 p.22) [VC]; enum regulation_reference "§8" for nicht_rhizomfest → §9 (STAGED note)', verified_at=now() where id='67f23442-0409-40ad-9409-2bf0fd79d25e' and verification_status not in ('verified_against_standard','corrected');

-- ---------- FLLTP-RHZ-19 Prüfbericht Erstellung ----------

-- bericht_datum — Musterbericht cover prints "Datum des Berichts: >> Tag. Monat. Jahr <<" (p.25)
update public.fields set verification_status='verified_against_standard', verification_quote='„Der Prüfbericht wurde am ........ erstellt und hat grundsätzlich eine Gültigkeitsdauer von 10 Jahren.“ Durch eine Bestätigung des Prüfinstituts kann die Gültigkeitsdauer des Prüfberichts in Zeitabschnitten von 5 Jahren verlängert werden, jedoch nur wenn die Prüfgrundlagen in wesentlichen Punkten nicht geändert wurden; das geprüfte Produkt noch dem aktuellen Lieferprogramm des Antragstellers entspricht; erneut Rückstellmuster beim Prüfinstitut hinterlegt werden (s. Abschnitt 5); der Hersteller durch eidesstattliche Erklärung zusichert, dass das Produkt sowie deren Herstellung und Fügetechnik mit dem geprüften Produkt identisch sind. — printed p.22', verification_note='md-verified 2026-09-05 (§9 p.22) [VC]; Musterbericht cover prints "Datum des Berichts: >> Tag. Monat. Jahr <<" (p.25); clause_reference §8 → §9 STAGED', verified_at=now() where id='5c1c9f97-1a9a-4467-81d9-caeafe08c06e' and verification_status not in ('verified_against_standard','corrected');

