-- ---------- FLLTP-RHZ-21 Konformitäts-Gesamtbescheinigung ----------

-- final_rhizom_conformity — duplicate of RHZ-18 pruefergebnis_rhizomfest (same enum)
update public.fields set verification_status='verified_against_standard', verification_quote='Ein Produkt gilt als rhizomfest, wenn in allen Prüfgefäßen nach Ablauf der Prüfdauer keine Rhizomeindringungen gemäß Abschnitt 2.9 sowie keine Rhizomdurchdringungen gemäß Abschnitt 2.10 festzustellen sind. Voraussetzung ist zudem, dass die in der Prüfung verwendeten Pflanzen in den Prüfgefäßen im gesamten Prüfungsverlauf eine ausreichende Wuchsleistung gemäß Abschnitt 2.7 erbracht haben. — printed p.11 | gilt daher als rhizomfest gegen Schilf und andere heimische aquatische rhizombildende Pflanzen nach dem FLL-Verfahren. (Hinweis: Bei der Verwendung von Bambusarten in Gewässernähe sind über diesen Rhizomschutz hinausgehende Schutzmaßnahmen erforderlich). — printed p.28', verification_note='md-verified 2026-09-05 (§3.11 p.11, Musterbericht p.28) [VC]; duplicate of RHZ-18 pruefergebnis_rhizomfest (same enum); clause_reference "§Gesamtbescheinigung" → §3.11/§9 STAGED', verified_at=now() where id='07e8b6bf-b4f7-49d3-978d-dc434cd75745' and verification_status not in ('verified_against_standard','corrected');

