-- bescheinigung_ausgestellt_durch — duplicate of RHZ-01 pruefinstitut_name
update public.fields set verification_status='verified_against_standard', verification_quote='Nach Beendigung des Versuchs ist von der jeweiligen Prüfinstitution ein vollständiger Prüfbericht in doppelter Ausführung (je ein Exemplar für das Prüfinstitut und den Auftraggeber) zu erstellen, jedoch nur, wenn sich das Produkt gemäß Abschnitt 2.11 als rhizomfest erwiesen hat. — printed p.22 | Durchführen der Auswertung (s. Abschnitt 7) und Erstellen des Prüfberichts (s. Abschnitt 8). Das Beschaffen der Gefäße (s. Abschnitt 4.2) kann vom Auftraggeber oder vom Prüfinstitut übernommen werden. — printed p.24', verification_note='md-verified 2026-09-05 (§9 p.22, §11 p.24) [VC]; duplicate of RHZ-01 pruefinstitut_name; clause_reference → §9 STAGED', verified_at=now() where id='5151f9ff-ed6b-41af-978d-4a4475e3f890' and verification_status not in ('verified_against_standard','corrected');

